1	// Plain helpers for the two model endpoints Haven uses (OpenAI-compatible;
2	// extraction can run on another provider, see extractionConfig). Not
3	// registered Convex functions; call these only from actions (they do network
4	// IO). fetch is available in the default Convex runtime, so no "use node".
5	
6	export type ExtractedProfile = {
7	  platform: string;
8	  name: string;
9	  handle?: string;
10	  headline?: string;
11	  bio?: string;
12	};
13	
14	const PLATFORMS = [
15	  "linkedin",
16	  "x",
17	  "instagram",
18	  "tiktok",
19	  "github",
20	  "facebook",
21	  "threads",
22	  "bluesky",
23	  "other",
24	] as const;
25	
26	// Strict structured-output schema: every property listed in required,
27	// optionality expressed as nullable types, per OpenAI strict mode rules.
28	const EXTRACTION_SCHEMA = {
29	  type: "object",
30	  additionalProperties: false,
31	  required: ["is_profile", "platform", "name", "handle", "headline", "bio"],
32	  properties: {
33	    is_profile: {
34	      type: "boolean",
35	      description:
36	        "True only if the screenshot shows a single person's social or professional profile.",
37	    },
38	    platform: { type: "string", enum: [...PLATFORMS] },
39	    name: {
40	      type: ["string", "null"],
41	      description: "The person's display name as shown.",
42	    },
43	    handle: {
44	      type: ["string", "null"],
45	      description: "The username or @handle if visible, without the URL.",
46	    },
47	    headline: {
48	      type: ["string", "null"],
49	      description:
50	        "The one line the platform shows as a title under the name -- a LinkedIn headline, a GitHub tagline. Many platforms have no such field: Instagram, TikTok and Threads show a bio there instead, and on those the answer is null and the text belongs in bio. Never a linked account, website, category label, follower count, or pronouns.",
51	    },
52	    bio: {
53	      type: ["string", "null"],
54	      description:
55	        "The person's own about text, wherever the platform puts it. On a platform with no headline this is where the text under the name goes.",
56	    },
57	  },
58	} as const;
59	
60	const EXTRACTION_PROMPT = [
61	  "This is a screenshot the user took of someone's social or professional profile.",
62	  "Identify which platform it is from (branding, layout, UI chrome) and extract",
63	  "the person's visible details. Only report what is actually visible; never",
64	  "guess a handle or invent text. If the image is not a person's profile,",
65	  "set is_profile to false.",
66	  // Without this the model fills headline with whatever sits under the name,
67	  // which on Instagram is the bio's linked account. headline is not an
68	  // identity field, but it is in the keyword haystack and in the embedding,
69	  // so the wrong text there makes a person findable by somebody else's
70	  // account name. A field the platform does not have is null, not guessed.
71	  "A field this platform does not have is null. Prefer null to a near miss.",
72	].join(" ");
73	
74	function requireEnv(name: string): string {
75	  const value = process.env[name];
76	  if (value === undefined || value === "") {
77	    throw new Error(
78	      `${name} is not set on the Convex deployment. Run: npx convex env set ${name} <value>`,
79	    );
80	  }
81	  return value;
82	}
83	
84	type Provider = { label: string; baseUrl: string; key: string };
85	
86	function openaiProvider(): Provider {
87	  return {
88	    label: "OpenAI",
89	    baseUrl: process.env.OPENAI_BASE_URL ?? "https://api.openai.com",
90	    key: requireEnv("OPENAI_API_KEY"),
91	  };
92	}
93	
94	// The two chat-completions callers are provider-swappable via
95	// <PREFIX>_BASE_URL / _API_KEY / _MODEL (any OpenAI-compatible API; we point
96	// extraction at interfaze.ai to spend credit there). Embeddings deliberately
97	// are not: the vector index stores 1536-dim text-embedding-3-small vectors,
98	// so moving them is a re-embed migration, not an env change.
99	function chatConfig(
100	  prefix: string,
101	  label: string,
102	  defaultModel: string,
103	): { provider: Provider; model: string } {
104	  const baseUrl = process.env[`${prefix}_BASE_URL`];
105	  const model = process.env[`${prefix}_MODEL`];
106	  if (baseUrl === undefined || baseUrl === "") {
107	    return {
108	      provider: openaiProvider(),
109	      model: model === undefined || model === "" ? defaultModel : model,
110	    };
111	  }
112	  // A custom base URL must bring its own key and model: falling back would
113	  // hand the OpenAI bearer to a third-party host, or send that host a model
114	  // name it does not serve.
115	  return {
116	    provider: { baseUrl, label, key: requireEnv(`${prefix}_API_KEY`) },
117	    model: requireEnv(`${prefix}_MODEL`),
118	  };
119	}
120	
121	function extractionConfig() {
122	  return chatConfig("EXTRACTION", "Extraction provider", "gpt-4o-mini");
123	}
124	
125	// Separate from extraction on purpose: reading one screenshot and reasoning
126	// over a whole network are different jobs, and the cheap vision model that
127	// suits the first is not automatically the right one for the second.
128	function askConfig() {
129	  return chatConfig("ASK", "Ask provider", "gpt-4o-mini");
130	}
131	
132	async function callProvider(
133	  provider: Provider,
134	  path: string,
135	  body: unknown,
136	): Promise<unknown> {
137	  const response = await fetch(`${provider.baseUrl}/v1/${path}`, {
138	    method: "POST",
139	    headers: {
140	      "Content-Type": "application/json",
141	      Authorization: `Bearer ${provider.key}`,
142	    },
143	    body: JSON.stringify(body),
144	  });
145	  if (!response.ok) {
146	    const detail = await response.text();
147	    throw new Error(
148	      `${provider.label} ${path} failed (${response.status}): ${detail}`,
149	    );
150	  }
151	  return await response.json();
152	}
