154	export async function extractProfile(
155	  imageUrl: string,
156	): Promise<ExtractedProfile> {
157	  const { provider, model } = extractionConfig();
158	  const result = (await callProvider(provider, "chat/completions", {
159	    model,
160	    messages: [
161	      {
162	        role: "user",
163	        content: [
164	          { type: "text", text: EXTRACTION_PROMPT },
165	          // "low", not "high": measured against four real profile
166	          // screenshots, high detail bought no extra accuracy -- same name,
167	          // same handle, decoy handles in the bio rejected either way -- and
168	          // cost about twice as much, because it sends the model into a long
169	          // reasoning pass rather than because the image costs more to read.
170	          { type: "image_url", image_url: { url: imageUrl, detail: "low" } },
171	        ],
172	      },
173	    ],
174	    response_format: {
175	      type: "json_schema",
176	      json_schema: {
177	        name: "profile_extraction",
178	        strict: true,
179	        schema: EXTRACTION_SCHEMA,
180	      },
181	    },
182	  })) as {
183	    choices?: Array<{ message?: { content?: string; refusal?: string } }>;
184	  };
185	
186	  const message = result.choices?.[0]?.message;
187	  if (message === undefined || typeof message.content !== "string") {
188	    throw new Error(message?.refusal ?? `${provider.label} returned no extraction`);
189	  }
190	  const parsed = JSON.parse(message.content) as {
191	    is_profile: boolean;
192	    platform: string;
193	    name: string | null;
194	    handle: string | null;
195	    headline: string | null;
196	    bio: string | null;
197	  };
198	
199	  const name = parsed.name?.trim() ?? "";
200	  if (!parsed.is_profile || name === "") {
201	    throw new Error("Could not read a profile in this screenshot");
202	  }
203	  const clean = (value: string | null): string | undefined => {
204	    const trimmed = value?.trim() ?? "";
205	    return trimmed === "" ? undefined : trimmed;
206	  };
207	  return {
208	    platform: parsed.platform,
209	    name,
210	    handle: clean(parsed.handle),
211	    headline: clean(parsed.headline),
212	    bio: clean(parsed.bio),
213	  };
214	}
