218	export type AskTurn = { role: "user" | "assistant"; text: string };
219	
220	export type AskAnswer = {
221	  matches: Array<{ ref: number; kind: "direct" | "bridge"; why: string }>;
222	  clarifyingQuestion?: string;
223	};
224	
225	const ASK_SCHEMA = {
226	  type: "object",
227	  additionalProperties: false,
228	  required: ["matches", "clarifying_question"],
229	  properties: {
230	    matches: {
231	      type: "array",
232	      items: {
233	        type: "object",
234	        additionalProperties: false,
235	        required: ["ref", "kind", "why"],
236	        properties: {
237	          ref: {
238	            type: "integer",
239	            description: "The #number of the person from the network listing.",
240	          },
241	          kind: {
242	            type: "string",
243	            enum: ["direct", "bridge"],
244	            description:
245	              "direct if this person matches the need themselves; bridge if they are a likely route to someone who does.",
246	          },
247	          why: {
248	            type: "string",
249	            description:
250	              "One sentence, in the user's own terms, citing what is written about this person.",
251	          },
252	        },
253	      },
254	    },
255	    clarifying_question: {
256	      type: ["string", "null"],
257	      description:
258	        "One question to ask instead of guessing, or null when the network can be answered as asked.",
259	    },
260	  },
261	} as const;
262	
263	const ASK_PROMPT = [
264	  "You are searching one person's private notes about people they know.",
265	  "Each entry below is one person: a #number, their details, and dated lines the user wrote about them.",
266	  "Answer only from these entries. Never invent a person, a fact, or a #number.",
267	  "",
268	  "Return a match as 'direct' when the person themselves fits the need.",
269	  "Return 'bridge' when nobody fits directly but this person is a plausible route to someone who does",
270	  "(for example: they work at a startup accelerator, so they likely know founders).",
271	  "A bridge must never be dressed up as a direct match, and its 'why' must say what the route is.",
272	  "",
273	  "If the request is too vague to answer without guessing, return no matches and ask exactly one",
274	  "clarifying question. Otherwise leave clarifying_question null.",
275	  "Order matches best first, and leave matches empty rather than padding it with weak ones.",
276	].join("\n");
