278	// The whole network in one call, which is what keeps this cheap: a personal
279	// network is hundreds of people, so there is no retrieval infrastructure to
280	// build, only a prompt to fit.
281	export async function askNetwork(
282	  query: string,
283	  dossiers: string,
284	  history: AskTurn[],
285	): Promise<AskAnswer> {
286	  const { provider, model } = askConfig();
287	  const result = (await callProvider(provider, "chat/completions", {
288	    model,
289	    messages: [
290	      { role: "system", content: ASK_PROMPT },
291	      { role: "user", content: `The network:\n\n${dossiers}` },
292	      ...history.map((turn) => ({ role: turn.role, content: turn.text })),
293	      { role: "user", content: query },
294	    ],
295	    response_format: {
296	      type: "json_schema",
297	      json_schema: { name: "network_answer", strict: true, schema: ASK_SCHEMA },
298	    },
299	  })) as {
300	    choices?: Array<{ message?: { content?: string; refusal?: string } }>;
301	  };
302	
303	  const message = result.choices?.[0]?.message;
304	  if (message === undefined || typeof message.content !== "string") {
305	    throw new Error(message?.refusal ?? `${provider.label} returned no answer`);
306	  }
307	  const parsed = JSON.parse(message.content) as {
308	    matches: Array<{ ref: number; kind: "direct" | "bridge"; why: string }>;
309	    clarifying_question: string | null;
310	  };
311	  const clarifying = parsed.clarifying_question?.trim() ?? "";
312	  return {
313	    matches: parsed.matches ?? [],
314	    clarifyingQuestion: clarifying === "" ? undefined : clarifying,
315	  };
316	}
317	
318	export async function embedText(text: string): Promise<number[]> {
319	  const result = (await callProvider(openaiProvider(), "embeddings", {
320	    model: "text-embedding-3-small",
321	    input: text,
322	  })) as { data?: Array<{ embedding?: number[] }> };
323	
324	  const embedding = result.data?.[0]?.embedding;
325	  if (embedding === undefined) {
326	    throw new Error("OpenAI returned no embedding");
327	  }
328	  return embedding;
329	}
