1	// Live recall for people:ask, run by hand rather than in CI: model output is
2	// not deterministic enough to gate a merge on, but "did the last prompt edit
3	// make this better or worse" is unanswerable without a number.
4	//
5	//   OPENAI_API_KEY=sk-... node scripts/eval-ask.ts
6	//   ASK_BASE_URL=https://api.interfaze.ai ASK_API_KEY=... ASK_MODEL=interfaze-beta \
7	//     node scripts/eval-ask.ts
8	//
9	// Node 24+ strips the types, so there is nothing to install. It talks to the
10	// provider directly and never touches a Convex deployment, because the
11	// fixtures carry their own prebuilt networks.
12	
13	import { ASK_FIXTURES, type AskFixture } from "../src/askFixtures.ts";
14	import { askNetwork, type AskAnswer } from "../convex/openaiClient.ts";
15	
16	// Each fixture runs this many times. One sample cannot tell a prompt that is
17	// reliably right from one that got lucky, and that difference is the only
18	// reason to measure at all.
19	const RUNS_PER_FIXTURE = Number(process.env.EVAL_RUNS ?? "3");
20	
21	type Outcome = {
22	  fixture: AskFixture;
23	  run: number;
24	  hit: boolean;
25	  detail: string;
26	};
27	
28	function grade(fixture: AskFixture, answer: AskAnswer): {
29	  hit: boolean;
30	  detail: string;
31	} {
32	  const got = answer.matches.map((match) => `#${match.ref} ${match.kind}`);
33	  if (fixture.expectClarification === true) {
34	    const asked = answer.clarifyingQuestion !== undefined;
35	    return {
36	      hit: asked && answer.matches.length === 0,
37	      detail: asked ? `asked: ${answer.clarifyingQuestion}` : `guessed: ${got.join(", ")}`,
38	    };
39	  }
40	  if (fixture.expected.length === 0) {
41	    return {
42	      hit: answer.matches.length === 0,
43	      detail: answer.matches.length === 0 ? "named nobody" : `named ${got.join(", ")}`,
44	    };
45	  }
46	  // Kind matters as much as identity: a bridge returned as a direct match is
47	  // the specific failure this feature is most likely to be trusted through.
48	  const missing = fixture.expected.filter(
49	    (want) =>
50	      !answer.matches.some(
51	        (match) => match.ref === want.ref && match.kind === want.kind,
52	      ),
53	  );
54	  return {
55	    hit: missing.length === 0,
56	    detail:
57	      missing.length === 0
58	        ? `found ${got.join(", ")}`
59	        : `missing ${missing.map((m) => `#${m.ref} ${m.kind}`).join(", ")}; got ${got.join(", ") || "nothing"}`,
60	  };
61	}
62	
63	const outcomes: Outcome[] = [];
64	for (const fixture of ASK_FIXTURES) {
65	  for (let run = 1; run <= RUNS_PER_FIXTURE; run++) {
66	    try {
67	      const answer = await askNetwork(fixture.query, fixture.network, []);
68	      const { hit, detail } = grade(fixture, answer);
69	      outcomes.push({ fixture, run, hit, detail });
70	    } catch (error) {
71	      // A provider failure is a failed run, not a crashed eval: the other
72	      // cases still carry information.
73	      outcomes.push({
74	        fixture,
75	        run,
76	        hit: false,
77	        detail: `error: ${error instanceof Error ? error.message : String(error)}`,
78	      });
79	    }
80	  }
81	}
82	
83	let passed = 0;
84	for (const fixture of ASK_FIXTURES) {
85	  const runs = outcomes.filter((outcome) => outcome.fixture === fixture);
86	  const hits = runs.filter((outcome) => outcome.hit).length;
87	  passed += hits;
88	  console.log(`\n${hits}/${runs.length}  ${fixture.name}`);
89	  console.log(`         query: ${fixture.query}`);
90	  console.log(`         why it matters: ${fixture.why}`);
91	  for (const run of runs) {
92	    console.log(`         run ${run.run}: ${run.hit ? "ok" : "MISS"} -- ${run.detail}`);
93	  }
94	}
95	
96	const total = outcomes.length;
97	console.log(
98	  `\nrecall ${passed}/${total} (${Math.round((passed / total) * 100)}%) over ${ASK_FIXTURES.length} cases x ${RUNS_PER_FIXTURE} runs`,
99	);
100	// Non-zero on any miss, so this can gate a prompt change without anyone
101	// having to read the output.
102	process.exit(passed === total ? 0 : 1);
